#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-26
# Evidence run for the method probes (fishwait29, FISH_METHOD_SHIM=1): lttng-only Autoware run (no timing claim: host stays
# off, no split), then the pipeline, then the extractor lines that show whether the tracker's deposit -> timer links became
# observed (`probe:band`) and the candidates closed. Usage: scripts/aw_method_probe_run_20261026.sh [log_dir]
set -u; cd "$(dirname "$0")/.."
LD=${1:-$HOME/fish_traces/aw_mprobe_20261026}; mkdir -p "$LD"
log() { echo "[$(date +%T)] $*" | tee -a "$LD/run.log"; }
IMG=${IMG:-autoware-dev-trt-a1000-fishwait29:latest}; MODES=${MODES:-lttng}
EV=ros2:fish_msg_retain,ros2:fish_msg_release,ros2:fish_msg_type,ros2:fish_msg_stamp,ros2:fish_msg_ids
docker image inspect "$IMG" >/dev/null 2>&1 || { log "image $IMG missing"; exit 2; }
[ -n "$(docker ps -q --filter name=ovh- --filter name=build_ --filter name=migf_)" ] && { log "another experiment container is running; refusing"; exit 3; }
AC=$(timeout 3 cat /sys/class/power_supply/AC/online 2>/dev/null); [ "$AC" = 1 ] || { log "AC adapter not online (AC/online=$AC); refusing"; exit 5; }
log "run: IMG=$IMG MODES=$MODES method shim=1 container shim=1 extra=$EV (host off, evidence run)"
echo "mprobe IMG=$IMG MODES=$MODES FISH_CONTAINER_SHIM=1 FISH_METHOD_SHIM=1 FISH_EXTRA_EVENTS=$EV" > "$LD/plan.txt"
FISH_ALLOW_FORK=1 NIGHT_RUNS_NO_SPLIT=1 bash scripts/night_runs.sh "$LD" < "$LD/plan.txt" >> "$LD/night_runs.out" 2>&1
L=$(grep "^mprobe " "$LD/night_runs.txt" | tail -1); log "night_runs: $L"
C=$(echo "$L" | awk '{print $2}'); RUN=$(ls -d "$C"/${MODES}_1 2>/dev/null | head -1)
[ -n "$RUN" ] && [ -f "$RUN/session.txt" ] || { log "no run dir / session.txt under $C"; exit 4; }
S=$(basename "$(cat "$RUN/session.txt")"); log "session $S"
log "launch log: $(grep -h 'method shim' "$RUN/launch.log" 2>/dev/null | head -2 | tr '\n' ' ')"
log "fish_method events: $(PGPASSWORD=fish psql -h localhost -U fish -d fish -At -c "SELECT count(*) FROM ros2_trace WHERE session_id='$S' AND event='ros2:fish_method'" 2>/dev/null) (before ingest this is 0)"
A=$HOME/fish_traces/analysis_$S
bash scripts/post_run_pipeline.sh "$RUN" "$A" > "$LD/pipeline.log" 2>&1 || log "pipeline rc=$?"
grep -E "FAILED|PIPELINE DONE|health:" "$LD/pipeline.log" | head -5 | sed 's/^/  /' | tee -a "$LD/run.log"
log "fish_method events ingested: $(PGPASSWORD=fish psql -h localhost -U fish -d fish -At -c "SELECT count(*) FROM ros2_trace WHERE session_id='$S' AND event='ros2:fish_method'")"
grep -E "method probes|candidates closed|join edges:|^vertices:" "$A/fish_tasks.txt" 2>/dev/null | cut -c1-330 | sed 's/^/  /' | tee -a "$LD/run.log"
python3 - "$A/fish_tasks.json" <<'PY' | tee -a "$LD/run.log"
import json, sys, collections
d = json.load(open(sys.argv[1])); VN = {v['id']: v for t in d['tasks'] for v in t['vertices']}
c = collections.Counter(e.get('prov') for t in d['tasks'] for e in t.get('edges', []) if e.get('kind') == 'join')
print('  join edge evidence:', dict(c))
for t in d['tasks']:
    for e in t.get('edges', []):
        if 'multi_object_tracker' in (VN.get(e['v'], {}).get('node') or '') and e.get('kind') == 'join':
            print(f"  tracker join: {VN[e['u']]['name'][-60:]} -> {VN[e['v']]['name'][-50:]} prov={e.get('prov')} n={e.get('n_pairs')} delta_p50={((e.get('delta') or {}).get('p50') or 0)/1e6:.1f} ms")
print('  remaining tracker candidates:', sum(1 for c_ in d['candidates'] if 'multi_object_tracker' in (VN.get(c_['v'], {}).get('node') or '')))
PY
log "METHOD PROBE RUN DONE: session $S, analysis $A"
